const jobs=[
 {title:'高级产品运营',company:'云杉互动',city:'上海',salary:'18-25K',exp:'3-5年',match:92,source:'公众号招聘',logo:'云',color:'#315b50'},
 {title:'用户增长运营',company:'拾光科技',city:'杭州',salary:'16-24K',exp:'3-5年',match:89,source:'企业官网',logo:'拾',color:'#765b45'},
 {title:'产品运营专家',company:'有山网络',city:'上海',salary:'20-30K',exp:'3-5年',match:87,source:'招聘网站',logo:'山',color:'#4c4a78'},
 {title:'增长策略运营',company:'极星出行',city:'上海',salary:'22-32K',exp:'3-5年',match:85,source:'公众号招聘',logo:'极',color:'#377087'},
 {title:'内容产品运营',company:'一页文化',city:'深圳',salary:'15-22K',exp:'2-4年',match:82,source:'公众号招聘',logo:'页',color:'#8a584d'},
 {title:'商业化产品运营',company:'木棉数据',city:'杭州',salary:'17-26K',exp:'3-5年',match:80,source:'企业官网',logo:'木',color:'#557048'}
];
const homeJobs=document.querySelector('#homeJobs'),allJobs=document.querySelector('#allJobs');
const savedName=localStorage.getItem('jobpilot-name')||'求职者';
function renderName(name){document.querySelectorAll('[data-user-name]').forEach(el=>el.textContent=name);document.querySelectorAll('[data-user-avatar]').forEach(el=>el.textContent=name.slice(0,1))}
renderName(savedName);
const resumeForm=document.querySelector('#resumeForm');
const resumeFields=['name','phone','email','target','location','education','summary','skills','experience','projects'];
function readResume(){return Object.fromEntries(resumeFields.map(key=>[key,resumeForm.querySelector(`[name="${key}"]`).value.trim()]))}
function updateResumePreview(data){document.querySelector('#previewName').textContent=data.name||'你的姓名';document.querySelector('#previewMeta').textContent=[data.target,data.education,data.location].filter(Boolean).join('｜')||'填写期望岗位和地点';document.querySelector('#previewContact').textContent=[data.phone,data.email].filter(Boolean).join('　｜　');document.querySelector('#previewSummary').textContent=data.summary||'填写后会显示在这里。';document.querySelector('#previewSkills').textContent=data.skills||'填写后会显示在这里。';document.querySelector('#previewExperience').textContent=data.experience||'填写后会显示在这里。';document.querySelector('#previewProjects').textContent=data.projects||'填写后会显示在这里。';if(data.name)renderName(data.name)}
function loadResume(){let data={};try{data=JSON.parse(localStorage.getItem('jobpilot-resume-v1')||'{}')}catch{};resumeFields.forEach(key=>{if(data[key])resumeForm.querySelector(`[name="${key}"]`).value=data[key]});updateResumePreview(readResume());if(Object.values(data).some(Boolean))document.querySelector('#resumeSaveState').textContent='已保存在本机'}
function saveResume(showToast=false){const data=readResume();localStorage.setItem('jobpilot-resume-v1',JSON.stringify(data));document.querySelector('#resumeSaveState').textContent='已保存在本机';updateResumePreview(data);if(data.name)localStorage.setItem('jobpilot-name',data.name);if(showToast){const toast=document.querySelector('#toast');toast.textContent='简历已保存到本机';toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),1800)}}
function applyResumeToJobSearch(data){if(data.target)document.querySelector('#jobSearch').value=data.target;if(data.skills)document.querySelector('#candidateSkills').value=[data.skills,data.education].filter(Boolean).join(' ');const city=document.querySelector('#cityFilter');if(data.location){const match=data.location.includes('增城')?'增城':data.location.includes('广州')?(data.location.includes('周边')?'广州及周边':'广州'):'广东';if([...city.options].some(option=>option.value===match))city.value=match}const level=document.querySelector('#candidateLevel');if(data.education.includes('大专'))level.value='大专';else if(data.education.includes('本科'))level.value='本科';else if(/硕士|博士|研究生/.test(data.education))level.value='硕士及以上';else if(/应届|毕业/.test(data.education))level.value='应届毕业生'}
loadResume();resumeForm.addEventListener('input',()=>{const data=readResume();updateResumePreview(data);saveResume()});resumeForm.addEventListener('submit',event=>{event.preventDefault();const data=readResume();saveResume(true);applyResumeToJobSearch(data);if(activeSearchGroup)searchOfficialJobs(activeSearchGroup,false)});document.querySelector('#printResume').onclick=()=>window.print();
function card(j){return `<article class="job-card" data-search="${j.title}${j.company}${j.city}"><span class="logo" style="background:${j.color}">${j.logo}</span><div><h3>${j.title}</h3><p>${j.company} · ${j.city} · ${j.salary}</p><div class="meta"><span class="tag">${j.exp}</span><span class="tag">${j.source}</span></div></div><div class="job-action"><span class="match">${j.match}% 匹配</span><button class="save-job">加入投递</button></div></article>`}
homeJobs.innerHTML=jobs.slice(0,3).map(card).join('');if(allJobs)allJobs.innerHTML=jobs.map(card).join('');
function showView(id){document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id===id));document.querySelectorAll('[data-view]').forEach(v=>v.classList.toggle('active',v.dataset.view===id));window.scrollTo({top:0,behavior:'smooth'});document.querySelector('.sidebar').classList.remove('open')}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));document.querySelectorAll('[data-view-target]').forEach(b=>b.onclick=()=>showView(b.dataset.viewTarget));
const modal=document.querySelector('#actionModal');function modalStep(step){document.querySelectorAll('.modal-step').forEach(s=>s.classList.toggle('active',s.dataset.step===step))}
function openModal(type){modal.classList.add('open');modal.setAttribute('aria-hidden','false');modalStep('input');const analyze=type==='analyze';document.querySelector('#modalTitle').textContent=analyze?'深度分析简历':'一键适配简历';document.querySelector('#modalDesc').textContent=analyze?'AI 将从内容、结构、关键词等 6 个维度诊断你的简历。':'粘贴职位描述，AI 会找出关键词并调整表达重点。';document.querySelector('#runAi').textContent=analyze?'开始深度分析':'开始智能适配 ↗'}
document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>openModal(b.dataset.action));document.querySelectorAll('.close,.close-result').forEach(b=>b.onclick=()=>modal.classList.remove('open'));modal.onclick=e=>{if(e.target===modal)modal.classList.remove('open')};
document.querySelector('#runAi').onclick=()=>{modalStep('loading');const lines=['提取岗位核心关键词','比对你的经历与岗位要求','生成更有说服力的表达'];let i=0;const t=setInterval(()=>{document.querySelector('#loadingText').textContent=lines[i++%lines.length]},550);setTimeout(()=>{clearInterval(t);modalStep('result')},1900)};
const savedJobs=new Set(JSON.parse(localStorage.getItem('jobpilot-saved')||'[]'));
document.querySelectorAll('.job-card').forEach(el=>{const title=el.querySelector('h3').textContent;if(savedJobs.has(title)){const b=el.querySelector('.save-job');b.textContent='已加入 ✓';b.disabled=true}});
document.addEventListener('click',e=>{if(e.target.classList.contains('save-job')){const title=e.target.closest('.job-card').querySelector('h3').textContent;savedJobs.add(title);localStorage.setItem('jobpilot-saved',JSON.stringify([...savedJobs]));document.querySelectorAll('.job-card').forEach(el=>{if(el.querySelector('h3').textContent===title){const b=el.querySelector('.save-job');b.textContent='已加入 ✓';b.disabled=true}});const toast=document.querySelector('#toast');toast.classList.add('show');setTimeout(()=>toast.classList.remove('show'),1800)}});
function searchPlans(group){const role=document.querySelector('#jobSearch').value.trim()||'适合岗位';const skills=document.querySelector('#candidateSkills').value.trim();const city=document.querySelector('#cityFilter').value;const level=document.querySelector('#candidateLevel').value;const schedule=document.querySelector('#workPreference').value;const benefits=document.querySelector('#benefitsPreference').value;const terms=[role,city,skills,level,schedule,benefits].filter(Boolean).join(' ');const plans={
500:[['企业招聘官网综合检索',`${terms} 五百强 企业招聘官网 社会招聘 校园招聘`],['广汽集团官网招聘',`${terms} 广汽集团 招聘 官网`],['广汽本田招聘平台',`${terms} 广汽本田 招聘 site:hotjob.cn`],['日立安斯泰莫招聘',`${terms} 日立安斯泰莫 增城 招聘`],['广州丰田招聘',`${terms} 广汽丰田 广州 招聘 官网`],['世界500强公司招聘公告',`${terms} 世界500强 公司官网 招聘公告 -猎聘 -BOSS`],['制造业与研发岗位',`${terms} 广州 制造业 500强 招聘官网`],['校招与应届岗位',`${terms} 广州 500强 校园招聘 官网`]],
foreign:[['外企官网综合检索',`${terms} 外企 官网 招聘 社招 校招`],['日系车企招聘',`${terms} 本田 丰田 广州 招聘 官网`],['日立系企业岗位',`${terms} 日立 广州 增城 招聘 官网`],['宝洁中国招聘',`${terms} 宝洁 中国 招聘 careers`],['外商投资企业招聘',`${terms} 增城 广州 外商投资企业 招聘官网`],['外企双休岗位',`${terms} 外企 双休 五险一金 招聘 官网`],['外企应届生岗位',`${terms} 跨国公司 广州 校园招聘 官网`],['外企专业岗位',`${terms} 广州 外企 职位 careers`]],
soe:[['广东省公共招聘平台',`${terms} site:hrss.gd.gov.cn/recruitment 招聘`],['广州政府招聘公告',`${terms} site:gz.gov.cn 招聘 公告`],['广东事业单位招聘',`${terms} site:gd.gov.cn 事业单位 公开招聘`],['增城区政府招聘',`${terms} site:zc.gov.cn 招聘 增城`],['国聘国企岗位',`${terms} site:iguopin.com 国企 招聘`],['广州国资企业招聘',`${terms} 广州 国资 国企 官网 招聘`],['事业单位公开招聘',`${terms} 事业单位 公开招聘 报名 官网`],['国企校招岗位',`${terms} 广州 国企 校园招聘 官网`]]
};return plans[group].map(([title,query])=>({title,query}))}
function escapeText(value){return String(value).replace(/[&<>"']/g,char=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[char]))}
let activeSearchGroup=null;
function renderOfficialSearchOptions(group,shouldScroll=true){activeSearchGroup=group;const plans=searchPlans(group);const groupName={500:'五百强企业',foreign:'优质外企',soe:'国企 / 事业单位'}[group];const results=document.querySelector('#searchResults');results.innerHTML=`<div class="search-results-head"><div><span class="eyebrow">${groupName} · Bing 官网优先检索</span><h3>已生成 ${plans.length} 条搜索入口</h3><p>点开任一入口，在 Bing 查看实时职位信息。</p></div></div><div class="search-result-grid">${plans.map(plan=>`<a class="search-result-card" target="_blank" rel="noopener noreferrer" href="https://cn.bing.com/search?q=${encodeURIComponent(plan.query)}"><span>官网优先</span><b>${escapeText(plan.title)}</b><small>${escapeText(plan.query)}</small><i>在 Bing 搜索 ↗</i></a>`).join('')}</div>`;if(shouldScroll)results.scrollIntoView({behavior:'smooth',block:'start'})}
function searchOfficialJobs(group){activeSearchGroup=group;const query=searchPlans(group)[0].query;window.location.assign(`https://cn.bing.com/search?q=${encodeURIComponent(query)}`)}
document.querySelector('#jobSearch').addEventListener('keydown',e=>{if(e.key==='Enter')searchOfficialJobs(activeSearchGroup||'500')});
document.querySelector('#search500Btn').onclick=()=>searchOfficialJobs('500');document.querySelector('#searchForeignBtn').onclick=()=>searchOfficialJobs('foreign');document.querySelector('#searchSoeBtn').onclick=()=>searchOfficialJobs('soe');
document.querySelector('#showMoreSearches').onclick=()=>renderOfficialSearchOptions(activeSearchGroup||'500');
['jobSearch','candidateSkills','cityFilter','candidateLevel','workPreference','benefitsPreference'].forEach(id=>{const field=document.querySelector('#'+id);field.addEventListener('input',()=>{if(activeSearchGroup)renderOfficialSearchOptions(activeSearchGroup,false)});field.addEventListener('change',()=>{if(activeSearchGroup)renderOfficialSearchOptions(activeSearchGroup,false)})});
document.querySelector('#authorizeWechat').onclick=()=>{document.querySelector('#articleState').innerHTML='<span>◷</span><b>等待配置开放平台</b><p>当前工程还没有微信第三方平台 AppID、审核权限和授权回调地址，暂时不能发起真实授权。</p>'};document.querySelector('#syncArticles').onclick=()=>{document.querySelector('#articleState').innerHTML='<span>◉</span><b>请先完成公众号授权</b><p>授权连接建立后，文章同步接口会在这里运行。</p>'};
document.querySelector('.mobile-menu').onclick=()=>document.querySelector('.sidebar').classList.toggle('open');
document.querySelector('.profile').onclick=()=>{const name=prompt('怎么称呼你？',localStorage.getItem('jobpilot-name')||'');if(name&&name.trim()){localStorage.setItem('jobpilot-name',name.trim());renderName(name.trim())}};
if('serviceWorker' in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./service-worker.js');
